    // A purely‐mathematical Fibonacci function, over naturals → integers.
    #[spec]
    #[verifier::decreases(n)]
    fn fib(n: nat) -> int {
        if n == 0 {
            0
        } else if n == 1 {
            1
        } else {
            fib(n - 1) + fib(n - 2)
        }
    }

    /// Returns the first `n` Fibonacci numbers in a Vec<i32>.
    /// 
    /// We prove:
    ///   1) The resulting vector has length `n`.
    ///   2) For each index `i < n`, `result[i] as int == fib(i)`.
    #[requires(true)]
    #[ensures(result.len() == n)]
    #[ensures(
        forall(|i: usize| i < n
            ==> result[i] as int == fib(i)
        )
    )]
    fn fibonacci(n: usize) -> Vec<i32> {
        // Even though the problem statement assumes n >= 2,
        // we can gracefully handle smaller n as well.
        if n == 0 {
            return Vec::new();
        } else if n == 1 {
            return vec![0];
        }

        // Pre-allocate a vector of length n for efficiency.
        let mut fibs = Vec::with_capacity(n);
        fibs.push(0);
        fibs.push(1);

        for i in 2..n {
            // According to the problem, no value will overflow i32.
            let next = fibs[i - 1] + fibs[i - 2];
            fibs.push(next);
        }

        fibs
    }

